// Scoped autogenerated-sidebar ordering.
//
// Goal: the left nav is autogenerated from the folder tree. We want MANUAL
// control over the top level (driven by `sidebar_position` / `_category_.json`
// `position`), but the sub-folders under the tool-catalog categories should be
// listed in alphabetical order by label instead of by hand-maintained positions.
//
// Alphabetized categories (matched by their `_category_.json` `label`):
//   - "Web Tools"         (web-tools/)
//   - "Desktop Tools" (desktop-tools/)
//
// This generator wraps the default one: it only re-sorts the direct children of
// those categories and leaves every other level — the top-level items and the
// pages *inside* each sub-folder — in whatever order the default generator
// produced.
const ALPHA_SORTED_CATEGORY_LABELS = new Set(['Web Tools', 'Desktop Tools']);

/**
 * @param {{ label?: string }} a
 * @param {{ label?: string }} b
 * @returns {number}
 */
function byLabel(a, b) {
  return (a.label ?? '').localeCompare(b.label ?? '', 'en', { ignorePunctuation: true });
}

/**
 * @param {Array<object>} items
 * @returns {Array<object>}
 */
function sortTargetedCategories(items) {
  return items.map((item) => {
    if (item.type === 'category' && ALPHA_SORTED_CATEGORY_LABELS.has(item.label)) {
      // Sort only this category's immediate children (the sub-folders).
      // Their inner pages keep the default order.
      return { ...item, items: [...item.items].sort(byLabel) };
    }
    return item;
  });
}

/**
 * @param {object} args
 * @param {(args: object) => Promise<Array<object>>} args.defaultSidebarItemsGenerator
 * @returns {Promise<Array<object>>}
 */
export default async function sortToolsSidebar({ defaultSidebarItemsGenerator, ...args }) {
  const items = await defaultSidebarItemsGenerator(args);
  return sortTargetedCategories(items);
}
